const { execSync } = require('child_process');

try {
  // Instala dependências Python
  const resultado = execSync('pip install rembg pillow numpy onnxruntime 2>&1 | tail -3', { timeout: 180000 }).toString();
  return [{ json: { status: 'deps_ok', log: resultado } }];
} catch(e) {
  // Tenta com pip3
  try {
    const resultado = execSync('pip3 install rembg pillow numpy onnxruntime 2>&1 | tail -3', { timeout: 180000 }).toString();
    return [{ json: { status: 'deps_ok', log: resultado } }];
  } catch(e2) {
    return [{ json: { status: 'deps_error', log: e2.message } }];
  }
}

const { execSync } = require('child_process');
const fs = require('fs');

// Garante que as pastas existem
try { fs.mkdirSync('/files/catalogo-entrada', { recursive: true }); } catch(e) {}
try { fs.mkdirSync('/files/catalogo-final', { recursive: true }); } catch(e) {}

// Lista imagens
let arquivos = [];
try {
  const saida = execSync('ls /files/catalogo-entrada/ 2>/dev/null | grep -iE "\\.(jpg|jpeg|png|webp)$" | sort').toString();
  arquivos = saida.trim().split('\n').filter(f => f.trim() !== '');
} catch(e) {
  arquivos = [];
}

if (arquivos.length === 0) {
  throw new Error('Nenhuma imagem encontrada em /files/catalogo-entrada/ — coloque as fotos lá antes de executar.');
}

return arquivos.map((arquivo, index) => ({
  json: {
    arquivo: arquivo.trim(),
    indice: index,
    codigo: 'REF-' + String(index + 1).padStart(3, '0'),
    caminho_entrada: '/files/catalogo-entrada/' + arquivo.trim(),
    caminho_saida: '/files/catalogo-final/REF-' + String(index + 1).padStart(3, '0') + '.png',
    total: arquivos.length
  }
}));

const { execSync } = require('child_process');
const fs = require('fs');

const entrada = $json.caminho_entrada;
const codigo = $json.codigo;
const saida = $json.caminho_saida;
const indice = $json.indice;

// Garante pasta de saída
try { fs.mkdirSync('/files/catalogo-final', { recursive: true }); } catch(e) {}

// Verifica se o script Python existe
if (!fs.existsSync('/files/editar_catalogo.py')) {
  throw new Error('Script Python não encontrado em /files/editar_catalogo.py — faça o upload do arquivo!');
}

// Verifica se a imagem existe
if (!fs.existsSync(entrada)) {
  throw new Error(`Imagem não encontrada: ${entrada}`);
}

let log = '';
let sucesso = false;

try {
  const cmd = `python3 /files/editar_catalogo.py "${entrada}" "${codigo}" "${saida}" 2>&1`;
  log = execSync(cmd, { timeout: 120000 }).toString();
  sucesso = fs.existsSync(saida);
} catch(e) {
  log = e.message;
  sucesso = false;
}

return [{
  json: {
    codigo: codigo,
    arquivo_original: $json.arquivo,
    caminho_saida: saida,
    sucesso: sucesso,
    mensagem: sucesso ? `✅ ${codigo} salvo com sucesso` : `❌ Erro em ${codigo}: ${log}`,
    log: log,
    timestamp: new Date().toISOString()
  }
}];

console.error('❌ ERRO:', $json.mensagem);
console.error('Log:', $json.log);
return [{ json: { ...$json, status: 'erro' } }];
